"""AC-M7-01: the OpenAPI generated by FastAPI has every path, method, body and response code of the contract."""

from __future__ import annotations

from pathlib import Path
from typing import Any, cast

import pytest
import yaml

from gxg_approval.api import Deps, create_app
from gxg_approval.crypto import Encryptor
from gxg_connector_kit.grants import BundleStore

REPO = next(p for p in Path(__file__).resolve().parents if (p / "uv.lock").exists())
CONTRACT = yaml.safe_load((REPO / "schemas/approval-service.openapi.yaml").read_text("utf-8"))
METHODS = ("get", "post", "put", "patch", "delete")
REFS = {
    "#/components/responses/IntentStatus": "intent-status.schema.json",
    "#/components/responses/Error": "error.schema.json",
}


@pytest.fixture(scope="module")
def generated(tmp_path_factory: pytest.TempPathFactory) -> dict[str, Any]:
    store = BundleStore({}, state_file=tmp_path_factory.mktemp("b") / "state.json")
    app = create_app(Deps("approval-api", cast(Any, None), store, Encryptor({}), {"keys": []}))
    return app.openapi()


OPERATIONS = [(path, m) for path, item in CONTRACT["paths"].items() for m in METHODS if m in item]


def test_contract_has_the_five_operations() -> None:
    assert len(OPERATIONS) == 5


@pytest.mark.parametrize(("path", "method"), OPERATIONS)
def test_operation(generated: dict[str, Any], path: str, method: str) -> None:
    want = CONTRACT["paths"][path][method]
    have = generated["paths"].get(path, {}).get(method)
    assert have is not None, f"{method.upper()} {path} missing"
    assert have["operationId"] == want["operationId"]

    def params(op: dict[str, Any]) -> set[tuple[str, str, bool]]:
        return {(p["name"], p["in"], p.get("required", False)) for p in op.get("parameters", [])}

    contract_params = {
        (p["name"], p["in"], p.get("required", False))
        for p in [
            CONTRACT["components"]["parameters"]["IntentId"] if "$ref" in p else p for p in want.get("parameters", [])
        ]
    }
    path_level = {(p["name"], p["in"], p.get("required", False)) for p in CONTRACT["paths"][path].get("parameters", [])}
    assert params(have) == contract_params | path_level
    if "requestBody" in want:
        assert have["requestBody"]["required"] is True
        assert (
            have["requestBody"]["content"]["application/json"]["schema"]
            == (want["requestBody"]["content"]["application/json"]["schema"])
        )
    else:
        assert "requestBody" not in have
    for code, response in want["responses"].items():
        assert code in have["responses"], f"{method.upper()} {path}: response {code} missing"
        got = have["responses"][code].get("content", {}).get("application/json", {}).get("schema")
        if "$ref" in response:
            assert got == {"$ref": REFS[response["$ref"]]}, code
        elif path.endswith("/dispatch"):
            assert got == response["content"]["application/json"]["schema"]
